// 888crypto.io

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract CRYPTO {
    string public name = "888CRYPTO";
    string public symbol = "$ETHER";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    address public treasury;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(address _treasury) {
        treasury = _treasury;
    }

    modifier CryptoStable() {
        require(msg.sender == treasury, "Not authorized");
        _;
    }

    function mint(address account, uint256 amount) external CryptoStable {
        totalSupply += amount;
        balanceOf[account] += amount;
    }

    function burn(address account, uint256 amount) external CryptoStable {
        totalSupply -= amount;
        balanceOf[account] -= amount;
    }

    function transfer(address recipient, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        require(balanceOf[sender] >= amount, "Insufficient balance");
        require(allowance[sender][msg.sender] >= amount, "Allowance exceeded");
        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        allowance[sender][msg.sender] -= amount;
        return true;
    }
}
